#include "helpers/CameraHelper.h"
#include "cameras/PerspectiveCamera.h"
#include "cameras/OrthographicCamera.h"
namespace{thread_local Vector3 vector;Camera& temporaryCamera(){static thread_local Camera value;return value;}}
CameraHelper::Data CameraHelper::createData(){Data data;std::vector<double> vertices,colors;const char* points[]={"n1","n2","n2","n4","n4","n3","n3","n1","f1","f2","f2","f4","f4","f3","f3","f1","n1","f1","n2","f2","n3","f3","n4","f4","p","n1","p","n2","p","n3","p","n4","u1","u2","u2","u3","u3","u1","c","t","p","c","cn1","cn2","cn3","cn4","cf1","cf2","cf3","cf4"};for(const auto* id:points){vertices.insert(vertices.end(),{0,0,0});colors.insert(colors.end(),{0,0,0});if(data.pointMap.get(id).isUndefined())data.pointMap.set(id,JSValue::array());auto indices=data.pointMap.get(id);indices.set(std::to_string(indices.length()),double(vertices.size()/3-1));}data.geometry=Helper_detail::geometry(vertices);data.geometry->setAttribute("color",std::make_shared<Float32BufferAttribute>(colors,3));return data;}
CameraHelper::CameraHelper(std::shared_ptr<Camera> camera):CameraHelper(std::move(camera),createData()){}
CameraHelper::CameraHelper(std::shared_ptr<Camera> value,Data data):LineSegments(data.geometry,Helper_detail::lineMaterial(0xffffff,true)),camera(std::move(value)),pointMap(std::move(data.pointMap)){type="CameraHelper";if(!camera)throw JSTypeError("Cannot read properties of undefined (reading 'updateProjectionMatrix')");if(auto perspective=std::dynamic_pointer_cast<PerspectiveCamera>(camera))perspective->updateProjectionMatrix();else if(auto orthographic=std::dynamic_pointer_cast<OrthographicCamera>(camera))orthographic->updateProjectionMatrix();matrix.aliasTo(std::shared_ptr<Matrix4>(camera,&camera->matrixWorld),camera);matrixAutoUpdate=false;update();setColors(Color(0xffaa00),Color(0xff0000),Color(0x00aaff),Color(0xffffff),Color(0x333333));}
CameraHelper& CameraHelper::setColors(const Color& frustum,const Color& cone,const Color& up,const Color& target,const Color& cross){const auto attribute=geometry->getAttribute("color");if(!attribute)throw JSTypeError("color attribute is undefined");for(double i=0;i<50;++i){const Color& color=i<24?frustum:i<32?cone:i<38?up:i<40?target:cross;attribute->setXYZ(i,color.r,color.g,color.b);}attribute->setNeedsUpdate(true);return *this;}
void CameraHelper::update(){const auto geometry=this->geometry;const auto points=pointMap;if(!camera)throw JSTypeError("camera is undefined");temporaryCamera().projectionMatrixInverse.copy(camera->projectionMatrixInverse);double nearZ,farZ;if(camera->reversedDepth){nearZ=1;farZ=0;}else if(camera->coordinateSystem==WebGLCoordinateSystem){nearZ=-1;farZ=1;}else if(camera->coordinateSystem==WebGPUCoordinateSystem){nearZ=0;farZ=1;}else throw std::runtime_error("THREE.CameraHelper.update(): Invalid coordinate system: "+std::to_string(camera->coordinateSystem));const auto point=[&](const char* key,double x,double y,double z){vector.set(x,y,z).unproject(temporaryCamera());const auto indices=points.get(key);if(!indices.isUndefined()){const auto position=geometry->getAttribute("position");if(!position)throw JSTypeError("position is undefined");for(double i=0,l=indices.get("length").toNumber();i<l;++i)position->setXYZ(indices.get(JSValue(i).toString()).toNumber(),vector.x,vector.y,vector.z);}};point("c",0,0,nearZ);point("t",0,0,farZ);point("n1",-1,-1,nearZ);point("n2",1,-1,nearZ);point("n3",-1,1,nearZ);point("n4",1,1,nearZ);point("f1",-1,-1,farZ);point("f2",1,-1,farZ);point("f3",-1,1,farZ);point("f4",1,1,farZ);point("u1",.7,1.1,nearZ);point("u2",-.7,1.1,nearZ);point("u3",0,2,nearZ);point("cf1",-1,0,farZ);point("cf2",1,0,farZ);point("cf3",0,-1,farZ);point("cf4",0,1,farZ);point("cn1",-1,0,nearZ);point("cn2",1,0,nearZ);point("cn3",0,-1,nearZ);point("cn4",0,1,nearZ);geometry->getAttribute("position")->setNeedsUpdate(true);}
std::shared_ptr<Object3D> CameraHelper::clone(bool)const{return std::make_shared<CameraHelper>(nullptr);}
void CameraHelper::dispose(){LineSegments::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);}
